{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Metolazone, the closest analogue (Morgan 0.3182), is a chlorinated benzenesulfonamide diuretic and has approximately 100% absolute oral bioavailability in humans, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Hydrochlorothiazide, a chlorinated benzenesulfonamide diuretic with 0.2712 similarity, has absolute oral bioavailability of 66–75% in healthy adults, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Bumetanide, a sulfonamide diuretic with 0.2083 similarity, has oral bioavailability of 0.664 ± 0.112 versus intravenous dosing in healthy subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Azosemide, a sulfonamide diuretic with 0.2535 similarity, has low oral bioavailability of 10–19% in humans, providing a contradictory low-F example; however, its tetrazole/thiophene scaffold and high first-pass metabolism make it less transferable to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a chlorinated benzenesulfonamide thiazide-like diuretic. The closest and most relevant analogues—metolazone (~100% F), hydrochlorothiazide (66–75%), and bumetanide (66–96%)—all show high oral bioavailability, strongly supporting F ≥ 20%. The low-F azosemide records are less transferable because of different heterocyclic structure and prominent first-pass metabolism. Overall prediction: high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is present in the provided evidence set.",
    "Azosemide demonstrates that some sulfonamide diuretics can have low F, so a human absolute bioavailability study for the query would further reduce residual uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

